param([string]$ProjectRoot=(Split-Path -Parent $PSScriptRoot))
$ErrorActionPreference='Stop'
if([Threading.Thread]::CurrentThread.ApartmentState-ne[Threading.ApartmentState]::STA){throw 'Run with powershell.exe -STA.'}
$halcon='C:\Program Files\MVTec\HALCON-20.11-Progress';$env:PATH=(Join-Path $halcon 'bin\x64-win64')+';'+$env:PATH
Add-Type -AssemblyName PresentationFramework
[Reflection.Assembly]::LoadFrom((Join-Path $halcon 'bin\dotnet35\halcondotnet.dll'))|Out-Null
$assembly=[Reflection.Assembly]::LoadFrom((Join-Path $ProjectRoot 'bin\x64\Debug\HalconWinFormsDemo.exe'))
function Assert([bool]$ok,[string]$message){if(-not$ok){throw $message}}
function Pump([int]$ms){$f=New-Object Windows.Threading.DispatcherFrame;$t=New-Object Windows.Threading.DispatcherTimer;$t.Interval=[TimeSpan]::FromMilliseconds($ms);$t.Add_Tick({$t.Stop();$f.Continue=$false});$t.Start();[Windows.Threading.Dispatcher]::PushFrame($f)}
$main=$assembly.GetType('HalconWinFormsDemo.MainWindow',$true);$helpType=$assembly.GetType('HalconWinFormsDemo.HelpCenterWindow',$true);$serviceType=$assembly.GetType('HalconWinFormsDemo.Services.RecipeService',$true);$loggerType=$assembly.GetType('HalconWinFormsDemo.Services.AppLogger',$true);$kindType=$assembly.GetType('HalconWinFormsDemo.Models.VmToolKind',$true)
$private=[Reflection.BindingFlags]'Instance,NonPublic';$all=[Reflection.BindingFlags]'Instance,NonPublic,Public';$temp=Join-Path([IO.Path]::GetTempPath())('halcon-s78-'+[Guid]::NewGuid().ToString('N'));[IO.Directory]::CreateDirectory($temp)|Out-Null
$service=$serviceType.GetConstructor([Type[]]@([string])).Invoke([object[]]@($temp.ToString()));$logger=$loggerType.GetConstructor([Type[]]@([string])).Invoke([object[]]@($temp.ToString()));$window=$main.GetConstructor($private,$null,[Type[]]@($serviceType,$loggerType),$null).Invoke([object[]]@($service,$logger))
$app=[Windows.Application]::Current;$owns=$null-eq$app;if($owns){$app=New-Object Windows.Application;$app.ShutdownMode=[Windows.ShutdownMode]::OnExplicitShutdown};$window.ShowInTaskbar=$false;$window.Left=-10000;$window.Show();Pump 200
function F([string]$name){$v=$main.GetField($name,$all).GetValue($window);Write-Output -NoEnumerate $v}
function M([string]$name,[object[]]$invokeArgs=@()){try{$method=@($main.GetMethods($private)|Where-Object Name -eq $name|Where-Object{$_.GetParameters().Count-eq$invokeArgs.Count}|Select-Object -First 1);if($null-eq$method){throw "Missing method $name/$($invokeArgs.Count)"};$method.Invoke($window,$invokeArgs)}catch [Reflection.TargetInvocationException]{throw $_.Exception.InnerException}}
function Out($tool,[string]$port){$value=$null;Assert($tool.TryGetOutputValue($port,[ref]$value))('Missing output '+$port+'; ResultCode='+$tool.ResultCode+'; Error='+$tool.ErrorMessage);Write-Output -NoEnumerate $value}
function LoadExample([string]$key){$main.GetField('isRecipeDirty',$private).SetValue($window,$false);M 'LoadExampleProgramS78' ([object[]]@($key))|Out-Null;Pump 120;@((F 'flowTools')|ForEach-Object{$_.PSObject.BaseObject})}
try{
  # A: formal Chinese help is generated from live tool metadata and opens directly on a selected module.
  $dataCodeKind=[Enum]::Parse($kindType,'DataCode2DRecognition');$nullableType=[Nullable``1].MakeGenericType($kindType);$help=$helpType.GetConstructor([Type[]]@($nullableType)).Invoke([object[]]@($dataCodeKind));$help.ShowInTaskbar=$false;$help.Left=-10000;$help.Show();Pump 160
  $topics=$helpType.GetField('allTopics',$private).GetValue($help);$expectedTopics=[Enum]::GetValues($kindType).Count+4;Assert($topics.Count-eq$expectedTopics) ('Help topic count mismatch: '+$topics.Count+' expected '+$expectedTopics)
  $topicList=$helpType.GetField('HelpTopicList',$all).GetValue($help);Assert($topicList.SelectedItem.ToolKind.ToString()-eq'DataCode2DRecognition') 'Current-module help did not select the requested tool'
  $document=$helpType.GetField('HelpDocument',$all).GetValue($help);$plain=New-Object Windows.Documents.TextRange -ArgumentList $document.ContentStart,$document.ContentEnd;Assert($plain.Text-match'QR Code'-and$plain.Text-match'DecodedText'-and$plain.Text-match'CodeCount') 'Module help lacks usage/input/output content'
  $search=$helpType.GetField('HelpSearchTextBox',$all).GetValue($help);$search.Text='Pose2D';Pump 80;Assert($topicList.Items.Count-ge1) 'Help search did not search descriptions or port-related module metadata';$help.Close()
  $manual=Join-Path $ProjectRoot 'docs\USER_MANUAL_ZH_CN.md';Assert((Test-Path $manual)-and([IO.File]::ReadAllText($manual).Length-gt4000)) 'Chinese user manual file is missing or incomplete'

  # B: every top-menu example creates a real editable flow with deterministic bindings, sample paths and unsaved protection.
  $basic=LoadExample 'basic-segmentation';Assert($basic.Count-eq8-and$basic[1].GetInputBinding('Image').SourceToolId-eq$basic[0].ToolId-and$basic[7].GetInputBinding('Value').SourceToolId-eq$basic[6].ToolId) 'Basic example flow/bindings are wrong';Assert(Test-Path $basic[0].Parameters.LocalImagePath) 'Basic example sample image missing'
  foreach($tool in $basic){M 'ExecuteFlowTool' ([object[]]@($tool,'S78 basic example'))|Out-Null};Assert($basic[0].ResultCode-eq'OK'-and$basic[7].ResultCode-match'OK|NG') 'Basic example did not execute through its real result judge'
  $qr=LoadExample 'data-code';Assert($qr.Count-eq4-and$qr[1].Kind.ToString()-eq'DataCode2DRecognition'-and$qr[2].GetInputBinding('String').SourcePortName-eq'DecodedText') 'Data-code example flow/bindings are wrong'
  M 'ExecuteFlowTool' ([object[]]@($qr[0],'S78 QR source'))|Out-Null;M 'ExecuteFlowTool' ([object[]]@($qr[1],'S78 QR decode'))|Out-Null;$decoded=[string](Out $qr[1] 'DecodedText');M 'ExecuteFlowTool' ([object[]]@($qr[2],'S78 QR text'))|Out-Null;M 'ExecuteFlowTool' ([object[]]@($qr[3],'S78 QR judge'))|Out-Null;Assert($qr[1].ResultCode-eq'OK'-and-not[string]::IsNullOrWhiteSpace($decoded)-and$qr[3].ResultCode-eq'OK') 'Data-code example did not execute its real decode/output chain'
  $contour=LoadExample 'contour-measurement';Assert($contour.Count-eq6-and$contour[3].GetInputBinding('XLD').SourceToolId-eq$contour[2].ToolId-and$contour[5].GetInputBinding('Value').SourcePortName-eq'MaxResidual') 'Contour example flow/bindings are wrong';Assert(Test-Path $contour[0].Parameters.LocalImagePath) 'Contour example sample image missing'
  $loadCount=$main.GetField('exampleProgramLoadCountS78',$private).GetValue($window);$lastKey=$main.GetField('lastExampleProgramKeyS78',$private).GetValue($window);$dirty=$main.GetField('isRecipeDirty',$private).GetValue($window);$recipePath=$main.GetField('currentRecipePath',$private).GetValue($window)
  Assert($loadCount-eq3-and$lastKey-eq'contour-measurement') 'Example load state did not track all three selections';Assert($dirty-eq$true) 'Example was not protected as an unsaved learning recipe';Assert([string]::IsNullOrWhiteSpace([string]$recipePath)) 'Example incorrectly became a formal saved recipe'
  Assert((F 'DeveloperToolbarPanel').Children.Count-eq7) 'S78 added a permanent toolbar button instead of a top menu';Assert((F 'ExampleProgramsMenuS78').Items.Count-eq3) 'Top example menu is incomplete'
  $xaml=[IO.File]::ReadAllText((Join-Path $ProjectRoot 'MainWindow.xaml'));Assert($xaml-match'ExampleProgramsMenuS78'-and$xaml-match'OpenChineseHelpMenuItem_ClickS78'-and@([regex]::Matches($xaml,'\bVM\b|VisionMaster')).Count-eq0) 'Help/example menu or branding contract failed'
  Write-Output ('S78_HELP_EXAMPLES=PASS; HelpTopics='+$topics.Count+'; Tools='+[Enum]::GetValues($kindType).Count+'; Examples='+$loadCount+'; QR='+$decoded+'; ToolbarChildren='+(F 'DeveloperToolbarPanel').Children.Count+'')
}finally{try{$main.GetField('recipeCloseConfirmed',$private).SetValue($window,$true);$window.Close()}catch{};if($owns){$app.Shutdown()};if(Test-Path $temp){Remove-Item -LiteralPath $temp -Recurse -Force}}
